_LOCKS_GUARD = threading.Lock()
_NOTEBOOK_LOCKS = {}
_PROCESS_LOCKS_GUARD = threading.Lock()
_PROCESS_LOCKS = {}
_PROCESS_LOCK_ROOT = Path(tempfile.gettempdir()) / "nbskill-notebook-locks"
_EXECUTION_SEMAPHORE = threading.RLock()

